"""Soundboard-Dateien überleben einen Neustart, Steckbriefbilder nicht."""

from hebocon.server import MediaStore


def test_board_survives_restart(tmp_path):
    store = MediaStore(tmp_path)
    meme = store.add(b"video", "video/mp4", "Meme", board=True)
    photo = store.add(b"png", "image/png", "robo.png", board=False)
    assert store.rename(meme["key"], "Neu")

    again = MediaStore(tmp_path)
    assert again.board == [{"key": meme["key"], "name": "Neu", "mime": "video/mp4"}]
    assert (tmp_path / meme["key"]).read_bytes() == b"video"
    assert not (tmp_path / photo["key"]).exists()

    again.remove(meme["key"])
    assert MediaStore(tmp_path).board == []
    assert not (tmp_path / meme["key"]).exists()
